css:
/* one dark tint over the whole window, so everything darkens evenly */
[data-mode="dark"] body { background-color: rgba(10, 10, 12, 0.42) !important; }
/* frosted glass for the message box, menus, dropdowns and dialogs, with a thin glass edge */
[data-mode="dark"] :is([role="menu"], [role="listbox"], [role="dialog"], .bg-surface-popover, .bg-surface-3) { -webkit-backdrop-filter: blur(30px) saturate(160%); backdrop-filter: blur(30px) saturate(160%); }
[data-mode="dark"] .bg-surface-3 { box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.08), inset 0 1px 0 rgb(255 255 255 / 0.06) !important; }
